import{_ as t,c as a,a0 as i,o as s}from"./chunks/framework.P9qPzDnn.js";const u=JSON.parse('{"title":"A++ Testing Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"testing.md","filePath":"testing.md"}'),l={name:"testing.md"};function n(r,e,o,p,h,c){return s(),a("div",null,e[0]||(e[0]=[i(`<h1 id="a-testing-documentation" tabindex="-1">A++ Testing Documentation <a class="header-anchor" href="#a-testing-documentation" aria-label="Permalink to &quot;A++ Testing Documentation&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This document describes the testing framework and test cases implemented for the A++ programming language compiler. The testing system is designed to verify the correct implementation of language features and catch potential regressions.</p><h2 id="test-structure" tabindex="-1">Test Structure <a class="header-anchor" href="#test-structure" aria-label="Permalink to &quot;Test Structure&quot;">​</a></h2><h3 id="_1-test-files" tabindex="-1">1. Test Files <a class="header-anchor" href="#_1-test-files" aria-label="Permalink to &quot;1. Test Files&quot;">​</a></h3><ul><li><code>comprehensive_test.a++</code>: Main test file containing all language feature tests</li><li><code>basic_test.a++</code>: Simple tests for basic functionality</li><li><code>run_tests.sh</code>: Test runner script that executes and verifies test outputs</li></ul><h3 id="_2-test-categories" tabindex="-1">2. Test Categories <a class="header-anchor" href="#_2-test-categories" aria-label="Permalink to &quot;2. Test Categories&quot;">​</a></h3><p>The comprehensive test suite covers the following categories:</p><h4 id="basic-print-tests" tabindex="-1">Basic Print Tests <a class="header-anchor" href="#basic-print-tests" aria-label="Permalink to &quot;Basic Print Tests&quot;">​</a></h4><ul><li>Integer printing</li><li>Float printing</li><li>String printing</li><li>Boolean printing (yup/nope)</li><li>Empty string printing</li><li>Escaped character printing</li></ul><h4 id="variable-tests" tabindex="-1">Variable Tests <a class="header-anchor" href="#variable-tests" aria-label="Permalink to &quot;Variable Tests&quot;">​</a></h4><ul><li>Integer variable declaration and assignment</li><li>Float variable declaration and assignment</li><li>String variable declaration and assignment</li><li>Boolean variable declaration and assignment</li><li>Variable reassignment</li><li>Variable-to-variable assignment</li></ul><h4 id="arithmetic-tests" tabindex="-1">Arithmetic Tests <a class="header-anchor" href="#arithmetic-tests" aria-label="Permalink to &quot;Arithmetic Tests&quot;">​</a></h4><ul><li>Addition</li><li>Subtraction</li><li>Multiplication</li><li>Division</li><li>Modulus</li><li>Operator precedence</li><li>Parenthesized expressions</li></ul><h4 id="loop-tests" tabindex="-1">Loop Tests <a class="header-anchor" href="#loop-tests" aria-label="Permalink to &quot;Loop Tests&quot;">​</a></h4><ul><li>Basic for loop functionality</li><li>Loop counter</li><li>Nested loops</li><li>Break statement</li></ul><h4 id="conditional-tests" tabindex="-1">Conditional Tests <a class="header-anchor" href="#conditional-tests" aria-label="Permalink to &quot;Conditional Tests&quot;">​</a></h4><ul><li>Basic if statements</li><li>if-else statements</li><li>Nested if statements</li><li>if-else chains</li></ul><h4 id="comparison-tests" tabindex="-1">Comparison Tests <a class="header-anchor" href="#comparison-tests" aria-label="Permalink to &quot;Comparison Tests&quot;">​</a></h4><ul><li>Less than (&lt;)</li><li>Greater than (&gt;)</li><li>Equal to (==)</li><li>Not equal to (!=)</li><li>Greater than or equal to (&gt;=)</li><li>Less than or equal to (&lt;=)</li></ul><h4 id="logical-operator-tests" tabindex="-1">Logical Operator Tests <a class="header-anchor" href="#logical-operator-tests" aria-label="Permalink to &quot;Logical Operator Tests&quot;">​</a></h4><ul><li>AND operator (&amp;&amp;)</li><li>OR operator (||)</li><li>NOT operator (!)</li><li>Combined logical expressions</li></ul><h2 id="test-runner-features" tabindex="-1">Test Runner Features <a class="header-anchor" href="#test-runner-features" aria-label="Permalink to &quot;Test Runner Features&quot;">​</a></h2><h3 id="_1-output-verification" tabindex="-1">1. Output Verification <a class="header-anchor" href="#_1-output-verification" aria-label="Permalink to &quot;1. Output Verification&quot;">​</a></h3><p>The test runner (<code>run_tests.sh</code>) includes:</p><ul><li>Colored output for pass/fail status</li><li>Section-by-section verification</li><li>Detailed error reporting</li><li>Full test output logging</li></ul><h3 id="_2-test-results" tabindex="-1">2. Test Results <a class="header-anchor" href="#_2-test-results" aria-label="Permalink to &quot;2. Test Results&quot;">​</a></h3><p>For each test case, the runner:</p><ul><li>Displays a checkmark (✓) for passed tests</li><li>Shows the test category and specific test</li><li>Provides the expected and actual output</li><li>Creates a detailed log file</li></ul><h3 id="_3-error-handling" tabindex="-1">3. Error Handling <a class="header-anchor" href="#_3-error-handling" aria-label="Permalink to &quot;3. Error Handling&quot;">​</a></h3><p>The test runner handles:</p><ul><li>Compiler errors</li><li>Runtime errors</li><li>Missing expected output</li><li>Unexpected output</li></ul><h2 id="recent-fixes-and-improvements" tabindex="-1">Recent Fixes and Improvements <a class="header-anchor" href="#recent-fixes-and-improvements" aria-label="Permalink to &quot;Recent Fixes and Improvements&quot;">​</a></h2><h3 id="_1-boolean-operations" tabindex="-1">1. Boolean Operations <a class="header-anchor" href="#_1-boolean-operations" aria-label="Permalink to &quot;1. Boolean Operations&quot;">​</a></h3><ul><li>Fixed logical operator evaluation (&amp;&amp;, ||, !)</li><li>Corrected output formatting for boolean values (yup/nope)</li><li>Added proper operator precedence handling</li></ul><h3 id="_2-test-runner-enhancements" tabindex="-1">2. Test Runner Enhancements <a class="header-anchor" href="#_2-test-runner-enhancements" aria-label="Permalink to &quot;2. Test Runner Enhancements&quot;">​</a></h3><ul><li>Added test timing information</li><li>Improved error message formatting</li><li>Added test categorization</li><li>Enhanced log file generation</li></ul><h2 id="running-tests" tabindex="-1">Running Tests <a class="header-anchor" href="#running-tests" aria-label="Permalink to &quot;Running Tests&quot;">​</a></h2><h3 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run all tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./run_tests.sh</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># View test logs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./logs/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">filnam</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.log</span></span></code></pre></div><h3 id="test-output-example" tabindex="-1">Test Output Example <a class="header-anchor" href="#test-output-example" aria-label="Permalink to &quot;Test Output Example&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Running A++ Comprehensive Tests...</span></span>
<span class="line"><span>✓ [Print] Found expected output: === Basic Print Tests ===</span></span>
<span class="line"><span>✓ [Print Integer] Found expected output: 42</span></span>
<span class="line"><span>✓ [Print Float] Found expected output: 3.14</span></span>
<span class="line"><span>...</span></span></code></pre></div><h2 id="adding-new-tests" tabindex="-1">Adding New Tests <a class="header-anchor" href="#adding-new-tests" aria-label="Permalink to &quot;Adding New Tests&quot;">​</a></h2><p>To add new tests:</p><ol><li>Add test cases to <code>comprehensive_test.a++</code></li><li>Update expected outputs in <code>run_tests.sh</code></li><li>Run the test suite to verify</li></ol><p>Example test case:</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Test category</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;=== New Feature Tests ===&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Test case with comment</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(some_expression);</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // Should print expected_output</span></span></code></pre></div><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><p><strong>Test Organization</strong></p><ul><li>Group related tests together</li><li>Add clear comments for expected output</li><li>Use consistent formatting</li></ul></li><li><p><strong>Test Coverage</strong></p><ul><li>Test both valid and invalid cases</li><li>Include edge cases</li><li>Test operator combinations</li></ul></li><li><p><strong>Maintenance</strong></p><ul><li>Update tests when language features change</li><li>Keep test output messages clear and descriptive</li><li>Document any special test cases</li></ul></li></ol>`,49)]))}const g=t(l,[["render",n]]);export{u as __pageData,g as default};
